/**
 * Horizontal Logo Primer Resmi Kementerian ESDM (FA LOGO ESDM 2025) + GeoMap Badan Geologi.
 * - Mode Terang (Positif): Perisai Kuning Energi #FFF500 dengan bingkai, ikon & logotype Hitam Mineral #000000.
 * - Mode Gelap (Negatif Kuning · Pedoman 3.3.9): Kuadran perisai transparan dengan garis, ikon & logotype #FFF500.
 * - Ukuran Digital Minimum: tinggi 41px (lebar ~101.6px >= 100px Pedoman 3.3.5) pada >=768px & safe zone 14px pada Desktop.
 */
export const EsdmLogo: React.FC<EsdmLogoProps> = ({ onClick, darkMode: darkModeProp }) => {
  const { darkMode: contextDarkMode } = useGeoMap();
  const isDark = darkModeProp ?? contextDarkMode;
  const fgColor = isDark ? '#FFF500' : '#000000';

  return (
    <button
      type="button"
      onClick={onClick}
      className="gm-press gm-focus group inline-flex items-center rounded-full px-1.5 py-1 text-left focus-visible:outline-none shrink-0 cursor-pointer"
      aria-label="Kembali ke Beranda Peta Interaktif GeoMap Kementerian ESDM"
    >
      <svg
        width="101.6"
        height="41"
        viewBox="0 0 259.91 104.86"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className="block h-[35px] md:h-[41px] w-auto shrink-0"
        role="img"
        aria-label="Kementerian ESDM"
      >
        {!isDark && <path d={ESDM_SHIELD_BG} fill="#FFF500" />}
        <path d={ESDM_SHIELD_FG_1} fill={fgColor} fillRule="nonzero" />
        <path d={ESDM_SHIELD_FG_2} fill={fgColor} fillRule="nonzero" />
        <path d={ESDM_WORDMARK_PATH} fill={fgColor} fillRule="nonzero" />
      </svg>

      {/* Mobile & Tablet lockup beside official Logo Primer */}
      <div
        className="ml-2.5 pl-2.5 md:ml-3 md:pl-3 flex lg:hidden items-center border-l h-6 shrink-0"
        style={{ borderColor: 'var(--s-border-strong)' }}
      >
        <div className="flex flex-col leading-tight">
          <span
            className="text-[11.5px] md:text-[12px] font-bold tracking-[-0.015em]"
            style={{ color: 'var(--s-text-primary)' }}
          >
            GeoMap
          </span>
          <span
            className="text-[9px] md:text-[9.5px] font-medium"
            style={{ color: 'var(--s-text-muted)' }}
          >
            Badan Geologi
          </span>
        </div>
      </div>

      {/* Desktop lockup with 1.5x safe zone clearspace (~14px) */}
      <div
        className="hidden lg:flex items-center ml-3.5 pl-3.5 border-l h-7 whitespace-nowrap"
        style={{ borderColor: 'var(--s-border-strong)' }}
      >
        <div className="flex flex-col leading-tight">
          <span
            className="text-[12.5px] font-bold tracking-[-0.015em]"
            style={{ color: 'var(--s-text-primary)' }}
          >
            GeoMap{' '}
            <span className="font-medium" style={{ color: 'var(--s-text-secondary)' }}>
              Badan Geologi
            </span>
          </span>
          <span className="text-[10px]" style={{ color: 'var(--s-text-muted)' }}>
            geologi.esdm.go.id/geomap
          </span>
        </div>
      </div>
    </button>
  );
};
